import {
    FileSystem,
    GUID,
    TelemetryFactory,
    type NowConfig,
    path,
    type Telemetry,
    unzipAppPackage,
} from '@servicenow/sdk-build-core'
import * as os from 'os'
import type { IConnector } from '../connector'
import { Project } from '../project'
import { traverseDirectory, writeFileStream } from '../util'
import { Parser } from '../context'
import { templates, type Templates, type TemplateFile, type TemplateInfo, type TemplateLeaf } from './templates'
import merge from 'lodash/merge'
import Handlebars from 'handlebars'

const ALLOWED_FILES_FOR_MERGE = ['package.json', 'now.config.json']

export class ProjectFactory {
    private readonly telemetry: Telemetry
    constructor(
        private readonly fs: FileSystem,
        telemetry?: Telemetry
    ) {
        this.telemetry = telemetry ?? TelemetryFactory.create()
    }

    public getProjectTemplates(): (TemplateInfo & { id: keyof Templates })[] {
        return (Object.entries(templates) as [keyof Templates, TemplateLeaf][])
            .filter(([, template]) => !template.info.partial && !template.info.configuration)
            .map(([id, template]) => ({
                ...template.info,
                id,
            }))
            .sort((a, b) => a.category.localeCompare(b.category) + a.name.localeCompare(b.name))
    }

    public getPartialTemplates(): (TemplateInfo & { id: keyof Templates })[] {
        return (Object.entries(templates) as [keyof Templates, TemplateLeaf][])
            .filter(([, template]) => template.info.partial)
            .map(([id, template]) => ({
                ...template.info,
                id,
            }))
            .sort((a, b) => a.category.localeCompare(b.category) + a.name.localeCompare(b.name))
    }

    public getConfigurationTemplate(): (TemplateInfo & { id: keyof Templates })[] {
        return (Object.entries(templates) as [keyof Templates, TemplateLeaf][])
            .filter(([, template]) => template.info.configuration)
            .map(([id, template]) => ({
                ...template.info,
                id,
            }))
            .sort((a, b) => a.category.localeCompare(b.category) + a.name.localeCompare(b.name))
    }

    public getOriginalFiles(workingDir: string): Record<string, string> {
        const originalFiles: Record<string, string> = {}
        for (const file of ALLOWED_FILES_FOR_MERGE) {
            const filePath = path.join(workingDir, file)
            if (FileSystem.existsSync(this.fs, filePath)) {
                originalFiles[file] = this.fs.readFileSync(filePath, { encoding: 'utf-8' })
            }
        }
        return originalFiles
    }

    public async createProjectFromApp(
        workingDir: string,
        scopeId: string,
        connector: IConnector,
        options: Partial<Pick<InitOptions, 'sdkVersion' | 'packageName'>>
    ): Promise<Project> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('init.from-instance')
            const metadata = await connector.download(scopeId, { method: 'complete' })

            if (!metadata.ok || !metadata.body) {
                const body = await metadata.json()
                if (body && typeof body.result === 'string') {
                    throw new Error(`Application download failed: ${body.result}`)
                }
                throw new Error(`Failed to download package for ${scopeId}`)
            }

            const tempDir = path.join(os.tmpdir(), GUID())

            this.fs.mkdirSync(tempDir, { recursive: true })

            const zipFile = path.join(tempDir, 'metadata.zip')

            await writeFileStream(this.fs, zipFile, metadata.body)

            const unzipDir = path.join(tempDir, 'metadata')

            await unzipAppPackage(this.fs, zipFile, unzipDir)

            const projectPromise = this.createProjectFromDirectory0(workingDir, unzipDir, options)

            this.telemetry.sendEvent(
                telemetryTimer.end({
                    data: { success: true, from: scopeId },
                })
            )

            return projectPromise
        } catch (error) {
            this.telemetry.error('init.from-instance', error)
            throw error
        }
    }

    public async createConfigurationProject(
        workingDir: string,
        connector: IConnector,
        scopeOptions: {
            scope: string | undefined
            scopeId: string | undefined
        },
        options: Partial<Pick<InitOptions, 'sdkVersion' | 'packageName'>>
    ): Promise<Project> {
        const { scope, scopeId } = scopeOptions
        const scopeResult = await connector.getScopeInfo(scope, scopeId ?? (scope === 'global' ? 'global' : undefined))

        if (!scopeResult) {
            throw new Error(`Scope must be present on instance to configure customizations `)
        }

        const projectSettings: InitOptions = {
            scopeId: scopeId ?? scopeResult?.appId,
            name: scopeResult.name,
            scope: scope ?? scopeResult.scope,
            packageName:
                options.packageName ??
                ProjectFactory.createNpmPackageName(`${scope ?? scopeResult.scope}-configuration`),
            description: scopeResult.shortDescription ?? '',
            sdkVersion: options.sdkVersion || 'latest',
            projectVersion: '0.0.1',
        }

        const errors = ProjectInitValidation.validateInitOptions(projectSettings)
        if (errors.length) {
            throw new Error(errors.join(', '))
        }

        const blankTemplateFiles = renderTemplates(templates.configuration.files, projectSettings, {})

        this.writeTemplates(workingDir, blankTemplateFiles)

        const proj = new Project({ fileSystem: this.fs, rootDir: workingDir, telemetryClient: this.telemetry })

        return proj
    }

    public async createProjectFromDirectory(
        workingDir: string,
        metadataDir: string,
        options: Partial<Pick<InitOptions, 'sdkVersion' | 'packageName'>>
    ): Promise<Project> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('init.from-fs')

            const proj = await this.createProjectFromDirectory0(workingDir, metadataDir, options)
            const { scopeId } = proj.getConfig()

            this.telemetry.sendEvent(
                telemetryTimer.end({
                    data: { success: true, from: scopeId },
                })
            )

            return proj
        } catch (error) {
            this.telemetry.error('init.from-fs', error)
            throw error
        }
    }

    private async createProjectFromDirectory0(
        workingDir: string,
        metadataDir: string,
        options: Partial<Pick<InitOptions, 'sdkVersion' | 'packageName'>>
    ): Promise<Project> {
        const sysAppXml = await this.findSysAppXmlInformation(metadataDir)

        if (!sysAppXml) {
            throw new Error('Failed to find a sys app xml file in application under path: ' + metadataDir)
        }

        const projectSettings: InitOptions = {
            scopeId: sysAppXml.scopeId,
            name: sysAppXml.name,
            scope: sysAppXml.scope,
            packageName: options.packageName || ProjectFactory.createNpmPackageName(sysAppXml.name),
            description: sysAppXml.shortDescription ?? '',
            sdkVersion: options.sdkVersion || 'latest',
            projectVersion: sysAppXml.version ?? '0.0.1',
        }

        const errors = ProjectInitValidation.validateInitOptions(projectSettings)
        if (errors.length) {
            throw new Error(errors.join(', '))
        }

        const blankTemplateFiles = renderTemplates(templates.base.files, projectSettings, {})
        const packageJsonTemplate = blankTemplateFiles.filter((f) => f.path === 'package.json')
        if (sysAppXml.packageJson) {
            const sysModuleFile = this.findPackageJsonModule(metadataDir, sysAppXml.packageJson)
            if (!sysModuleFile) {
                throw new Error(
                    `The sys_app xml file contains package_json field but no matching package.json sys_module was found in the application.`
                )
            }
            packageJsonTemplate[0]!.content = sysModuleFile
        }
        this.writeTemplates(workingDir, blankTemplateFiles)

        const proj = new Project({ fileSystem: this.fs, rootDir: workingDir, telemetryClient: this.telemetry })

        FileSystem.copySync(this.fs, metadataDir, proj.getMetadataDir(), {
            filter: (file) => !file.startsWith('sys_module'),
        })

        return proj
    }

    private findPackageJsonModule(metadataDir: string, packageJson: string): string | undefined {
        let packageJsonModule: string | undefined
        const sysModuleFiles: string[] = []
        traverseDirectory(this.fs, metadataDir, {
            visitor: (file) => {
                if (path.basename(file).startsWith('sys_module')) {
                    sysModuleFiles.push(file)
                }
            },
            extensions: ['.xml'],
        })
        for (const sysModuleFile of sysModuleFiles) {
            const content = this.fs.readFileSync(sysModuleFile, { encoding: 'utf-8' })
            if (content.includes(packageJson)) {
                const cdataRegex = /<content><!\[CDATA\[([\s\S]*?)\]\]><\/content>/
                const match = content.match(cdataRegex)
                if (match && match[1]) {
                    packageJsonModule = match[1]
                    break
                }
            }
        }
        return packageJsonModule
    }

    public createProject(workingDir: string, options: InitOptions): Project {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('createProject')
            const errors = ProjectInitValidation.validateInitOptions(options)
            if (errors.length) {
                throw new Error(errors.join(', '))
            }

            const projectSettings: InitOptions = {
                ...options,
                scopeId: options.scopeId || GUID(),
            }

            const blankTemplateFiles = renderTemplates(templates.base.files, projectSettings, {})
            this.writeTemplates(workingDir, blankTemplateFiles)
            if (projectSettings.templateId && projectSettings.templateId !== 'base') {
                const originalFiles = this.getOriginalFiles(workingDir)
                const templateRenderedFiles = renderTemplates(
                    templates[projectSettings.templateId].files,
                    projectSettings,
                    originalFiles
                )
                this.writeTemplates(workingDir, templateRenderedFiles)
            }

            const project = new Project({ fileSystem: this.fs, rootDir: workingDir, telemetryClient: this.telemetry })

            this.telemetry.sendEvent(
                telemetryTimer.end({
                    data: {
                        success: true,
                        ...options,
                    },
                })
            )

            return project
        } catch (error) {
            this.telemetry.error('createProject', error)
            throw error
        }
    }

    private async findSysAppXmlInformation(directory: string): Promise<
        | {
              name: string
              version: string
              shortDescription: string | undefined
              scope: string
              scopeId: string
              packageJson: string | undefined
          }
        | undefined
    > {
        const sysAppPath = this.getSysAppXML(directory)
        if (!sysAppPath) {
            return undefined
        }

        const parser = new Parser(new Project(), [], [])
        const [record] = await parser.parsePayload({
            path: sysAppPath,
            content: this.fs.readFileSync(sysAppPath).toString('utf-8'),
        })
        if (!record) {
            throw new Error(`Error parsing ${sysAppPath}. Check the sys_app XML file and try again.`)
        }

        return {
            name: record.get('name').asString('sys_app record must have a name').getValue(),
            version: record.get('version').asString('sys_app record must have a version').getValue(),
            shortDescription: record.get('short_description').ifString()?.getValue(),
            scope: record.get('scope').asString('sys_app record must have a scope').getValue(),
            scopeId: record.getId().getValue(),
            packageJson: record.get('package_json').ifString()?.getValue(),
        }
    }

    private getSysAppXML(directory: string): string | undefined {
        const appRegex = /^sys_app_[0-9a-f]{32}\.xml$/
        const storeAppRegex = /^sys_store_app_[0-9a-f]{32}\.xml$/
        // sys_app or sys_store_app file can be in root metadata
        // directory, the scope directory, or within the update directory
        const findAppXml = (subdir: string, prefix: RegExp) => {
            const dir = path.join(directory, subdir)
            if (FileSystem.existsSync(this.fs, dir)) {
                const dirItems = this.fs.readdirSync(dir)
                const appXml = dirItems.find((item) => prefix.test(item))
                return appXml && path.join(dir, appXml)
            }

            return undefined
        }

        const rootDir = ''

        return (
            findAppXml(rootDir, appRegex) ||
            findAppXml('update', appRegex) ||
            findAppXml('scope', appRegex) ||
            findAppXml(rootDir, storeAppRegex) ||
            findAppXml('update', storeAppRegex) ||
            findAppXml('scope', storeAppRegex)
        )
    }

    private writeTemplates(directory: string, templates: TemplateFile[]): void {
        for (const [, template] of Object.entries(templates)) {
            const filePath = path.join(directory, template.path)
            this.fs.mkdirSync(path.dirname(filePath), { recursive: true })
            this.fs.writeFileSync(filePath, template.content)
        }
    }

    public static createNpmPackageName(appName: string): string {
        // Convert to lowercase
        let name = appName.toLowerCase()
        // Replace invalid characters with a hyphen
        name = name.replace(/[^a-z0-9-_.]+/g, '-')
        //truncate to 210 characters
        name = name.substring(0, 210)
        // Remove leading or trailing hyphens
        name = name.replace(/^-+|-+$/g, '')

        return name
    }
}

export type InitOptions = Pick<NowConfig, 'name' | 'scope'> & {
    scopeId?: string
    packageName: string
    description: string
    sdkVersion?: string
    projectVersion?: string
    templateId?: keyof Templates
}

export const ProjectInitValidation = {
    validateInitOptions(options: InitOptions): string[] {
        const errors: string[] = []

        const appNameError = ProjectInitValidation.validateAppName(options.name)
        if (appNameError) {
            errors.push(`appName ${appNameError}`)
        }

        const scopeNameError = ProjectInitValidation.validateScopeName(options.scope)
        if (scopeNameError) {
            errors.push(`scopeName ${scopeNameError}`)
        }

        const packageNameError = ProjectInitValidation.validateNpmPackageName(options.packageName)
        if (packageNameError) {
            errors.push(`packageName ${packageNameError}`)
        }

        return errors
    },

    validateAppName(name: string | undefined): string | void {
        if (!name) {
            return `cannot be empty`
        }

        if (name.length > 100) {
            return `exceeds 100 characters`
        }

        if (name.length < 4) {
            return `must be at least 4 characters long`
        }
    },

    validateScopeName(name: string | undefined, requiredPrefix?: string | undefined): string | void {
        const errors: string[] = []
        if (!name) {
            return `cannot be empty`
        }

        if (name.length < 4) {
            errors.push('must be at least 4 characters long')
        }

        if (name.length > 18) {
            errors.push('must be less than 19 characters')
        }

        if (name.endsWith('_')) {
            errors.push('cannot end in an underscore')
        }

        if (name.includes('__')) {
            errors.push('cannot contain double underscore')
        }

        if (/[^a-z0-9_]/.test(name)) {
            errors.push('can only contain lowercase alphanumeric characters and underscores')
        }

        // Matching NowConfig validation
        if (!/^((x|sn)_[a-z0-9_]+|global)$/.test(name)) {
            errors.push(`must match pattern 'x/sn_<vendor>_<name>'`)
        }

        if (requiredPrefix) {
            if (name === requiredPrefix) {
                errors.push(`must not exactly match prefix "${requiredPrefix}"`)
            }

            if (!name.startsWith(requiredPrefix)) {
                errors.push(`must start with prefix "${requiredPrefix}"`)
            }
        }

        if (errors.length) {
            const listJoin = new Intl.ListFormat('default', {
                style: 'long',
                type: 'conjunction',
            })
            return `Invalid scope: ${listJoin.format(errors)}`
        }
    },

    validateNpmPackageName(name: string | undefined): string | void {
        if (!name) {
            return `cannot be empty`
        }

        if (name.length > 214) {
            return 'name must be less than or equal to 214 characters'
        }

        // mIxeD CaSe nAMEs
        if (name.toLowerCase() !== name) {
            return 'name can no longer contain capital letters'
        }

        if (/[~'!()*]/.test(name.split('/').slice(-1)[0]!)) {
            return 'name can no longer contain special characters ("~\'!()*")'
        }

        if (encodeURIComponent(name) !== name) {
            // Maybe it's a scoped package name, like @user/package
            const nameMatch = name.match(/@([^/]+)\/([^/]+)/)
            if (nameMatch) {
                const user = nameMatch[1]!
                const pkg = nameMatch[2]!
                if (encodeURIComponent(user) === user && encodeURIComponent(pkg) === pkg) {
                    return
                }
            }

            return 'name can only contain URL-friendly characters'
        }
    },
}

type RenderedTemplateFile = TemplateFile & { templateFile: TemplateFile }

// templates used during convert/create
export const renderTemplates = (
    templates: TemplateFile[],
    data: Record<string, unknown>,
    originalFiles: Record<string, string>
): RenderedTemplateFile[] => {
    // Explicitly type `this` to satisfy the `noImplicitThis` TypeScript compiler option.
    Handlebars.registerHelper(
        'mergeJsonFiles',
        function (this: unknown, path: string, options: Handlebars.HelperOptions) {
            const patchJson = options.fn(this).trim()
            let patch: object
            let originalJson: object
            try {
                patch = JSON.parse(patchJson)
                originalJson = JSON.parse(originalFiles[path] || '{}')
            } catch (e: any) {
                throw new Error(`Invalid JSON in mergeJsonFiles block:\n${e?.message}`)
            }
            const merged = merge(originalJson, patch)
            return JSON.stringify(merged, null, 2)
        }
    )

    const output: RenderedTemplateFile[] = []
    for (const templateFile of templates) {
        const compiledPathTemplate = Handlebars.compile(templateFile.path)
        const path = compiledPathTemplate({
            ...data,
        })
        // content template can use mergeJsonFiles helper
        const compiledContentTemplate = Handlebars.compile(templateFile.content)
        const content = compiledContentTemplate({
            ...data,
        })
        output.push({
            templateFile,
            path,
            content,
        })
    }
    return output
}

export { templates }
export type { Templates, TemplateFile, TemplateInfo, TemplateLeaf }
